TLM.f("Sancti/03-19",{"officium":"S. Joseph Sponsi B.M.V. Confessoris","rule":["Gloria","Credo","Prefatio=Joseph=Festivitáte;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 91:13-14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."}],"Oratio":[{"k":"text","la":"Sanctíssimæ Genetrícis tuæ Sponsi, quǽsumus, Dómine, méritis adjuvémur: ut, quod possibílitas nostra non óbtinet, ejus nobis intercessióne donétur:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 45:1-6"},{"k":"text","la":"Diléctus Deo et homínibus, cujus memória in benedictióne est. Símilem illum fecit in glória sanctórum, et magnificávit eum in timóre inimicórum, et in verbis suis monstra placávit. Glorificávit illum in conspéctu regum, et jussit illi coram pópulo suo, et osténdit illi glóriam suam. In fide et lenitáte ipsíus sanctum fecit illum, et elégit eum ex omni carne. Audívit enim eum et vocem ipsíus, et indúxit illum in nubem. Et dedit illi coram præcépta, et legem vitæ et disciplínæ."}],"Graduale":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Dómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"text","la":"Vitam pétiit a te, et tribuísti ei longitúdinem diérum in sǽculum sǽculi.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja."},{"k":"ref","la":"Osee 14. 6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 1:18-21"},{"k":"text","la":"Cum esset desponsáta Mater Jesu María Joseph, ántequam convenírent, invénta est in útero habens de Spíritu Sancto. Joseph autem, vir ejus, cum esset justus et nollet eam tradúcere, vóluit occúlte dimíttere eam. Hæc autem eo cogitánte, ecce, Angelus Dómini appáruit in somnis ei, dicens: Joseph, fili David, noli timére accípere Maríam cónjugem tuam: quod enim in ea natum est, de Spíritu Sancto est. Páriet autem fílium, et vocábis nomen ejus Jesum: ipse enim salvum fáciet pópulum suum a peccátis eórum."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Débitum tibi, Dómine, nostræ réddimus servitútis, supplíciter exorántes: ut, suffrágiis beáti Joseph, Sponsi Genetrícis Fílii tui Jesu Christi, Dómini nostri, in nobis tua múnera tueáris, ob cujus venerándam festivitátem laudis tibi hóstias immolámus."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Matt 1:20"},{"k":"text","la":"Joseph, fili David, noli timére accípere Maríam cónjugem tuam: quod enim in ea natum est, de Spíritu Sancto est. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Adésto nobis, quǽsumus, miséricors Deus: et, intercedénte pro nobis beáto Joseph Confessóre, tua circa nos propitiátus dona custódi."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6b4668e2db0b0991":{"t":"Ps 91, 13-14, Ps 91, 2\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega. (Ps 91, 2) Dobro je slaviti Gospodina, i pjevati tvojemu imenu, Svevišnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega."},"207179b9f73c5c97":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da nam pomognu zasluge Zaručnika presvete tvoje Majke, te njegovim zagovorom zadobijemo što ne možemo postići svojom slabošću:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"11efe36a44cd32d9":{"t":"Sir 45, 1-6\nČitanje knjige Mudrosti: Bogu je i ljudima drag, njegova je uspomena blagoslovljena. Gospodin mu je udijelio slavu kao svetima, i dao mu moć, da ga se boje neprijatelji. Na njegovu riječ prestaju strahote. Proslavio ga je pred vladarima, dao mu je zapovijedi pred narodom i pokazao mu svoju slavu. Posvetio ga je poradi njegove vjernosti i krotkosti, izabrao ga između svih ljudi. Čuo je njegov glas i uveo ga u oblak. On mu je sam dao zapovijedi, zakon života i mudrosti."},"6a5c7277f15ac135":{"t":"Ps 20, 4-5\nGospodine, pretekao si ga obilnim blagoslovima, na glavu si mu stavio krunu od dragog kamenja. U tebe je tražio život, i ti si mu dao dug život u vijeke vjekova.\n\nPs 111, 1-3\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. Silno će biti na zemlji njegovo potomstvo, rod će pravednika biti blagoslovljen. U njegovu je domu slava i bogatstvo, i njegova pravednost ostaje u vijeke vjekova."},"9eccaaf16939309e":{"t":"Mt 1, 18-21\nSlijedi sveto Evanđelje po Mateju. Kad je Isusova majka Marija bila zaručena s Josipom, prije nego se nastaniše zajedno, nađe se da je začela po Duhu Svetomu. Njezin muž Josip, jer je bio pravedan te je nije htio javno osramotiti, bavio se mišlju da je potajno otpusti. Ali, dok je on to razmišljao, ukaza mu se u snu anđeo i reče: Josipe, Davidov sine, nemoj se bojati uzeti k sebi svoju ženu Mariju, jer je ono što je u njoj začeto od Duha Svetoga. Ona će roditi Sina, i nadjeni mu ime Isus, jer će on spasiti svoj narod od njegovih grijeha."},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć."},"802fd91b931a3169":{"t":"Izvršavajući, Gospodine, dužnost naše službe ponizno te molimo, da u nama čuvaš svoje darove zagovorom blaženoga Josipa, zaručnika Majke tvoga Sina Isusa Krista, našega Gospodina, na čiju časnu svetkovinu prinosimo tebi žrtvu hvale.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"72f5656e922793a7":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zavaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: – i da te <i>o svetkovini</i> blaženoga Josipa doličnim pohvalama veličamo, blagoslivljamo i slavimo. On je onaj pravednik koga si dao za zaručnika Bogorodici Djevici; i onaj vjerni i mudri sluga koga si postavio nad svojom obitelji da umjesto oca čuva tvoga Jedinorođenca, začeta po Duhu Svetom, Isusa Krista, Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"f8e1bc0ef37aac91":{"t":"Mt 1, 20\nJosipe, Davidov sine, nemoj se bojati uzeti k sebi svoju ženu Mariju, jer je ono, što je u njoj začeto, od Duha Svetoga."},"adbdacf479b210ff":{"t":"<i>Pomolimo se</i>.\nBudi s nama, molimo, milosrdni Bože, i na pomirni zagovor blaženoga Josipa, priznavaoca, čuvaj u nama svoje darove.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"ab3a36a2f3b9a324":{"t":"Ps 91, 13-14, Ps 91, 2\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega. (Ps 91, 2) Dobro je slaviti Gospodina, i pjevati tvojemu imenu, Svevišnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega.","v":"∅ → aleluia aleluia; ∅ → aleluia aleluia"},"ef86f28d488eaa31":{"t":"Sir 45, 9, Hoš 14, 6\n<i>Aleluja</i>, <i>aleluja</i>.\n(Sir 45,9) Gospodin ga je ljubio i ukrasio, zaodjenuo ga je haljinom slave. <i>Aleluja</i>.\n(Hoš 14, 6) Pravednik raste kao ljiljan i vječno cvate pred Gospodinom. <i>Aleluja</i>."},"668d2b3f25be2f1c":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć. <i>Aleluja</i>."},"a91e3e0bdb15957c":{"t":"Mt 1, 20\nJosipe, Davidov sine, nemoj se bojati uzeti k sebi svoju ženu Mariju, jer je ono, što je u njoj začeto, od Duha Svetoga.","v":"∅ → aleluia"}}});
